const input = $input.first().json;
const html = String(input.indexHtml ?? input.body ?? input.data ?? "");
if (!html || html.length < 500) throw new Error("ONAGRI archive response is empty or unexpectedly short");
const decode = s => String(s).replace(/&amp;/g,"&").replace(/&#39;|&apos;/g,"'").replace(/&quot;/g,'"').replace(/&nbsp;/g," ").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&#(\\d+);/g,(_,n)=>String.fromCodePoint(Number(n))).replace(/&#x([0-9a-f]+);/gi,(_,n)=>String.fromCodePoint(parseInt(n,16)));
const strip = s => decode(s.replace(/<script[\\s\\S]*?<\\/script>/gi," ").replace(/<style[\\s\\S]*?<\\/style>/gi," ").replace(/<[^>]+>/g," ")).replace(/\\s+/g," ").trim();
const monthNames = ["janvier","fevrier","février","mars","avril","mai","juin","juillet","aout","août","septembre","octobre","novembre","decembre","décembre"];
const links = [];
for (const match of html.matchAll(/<a\\b([^>]*)>([\\s\\S]*?)<\\/a>/gi)) {
  const href = match[1].match(/href\\s*=\\s*["']([^"']+)["']/i)?.[1];
  const label = strip(match[2]);
  if (!href || !/Mercuriale Bir El Kassaa/i.test(label)) continue;
  const year = label.match(/20\\d{2}/)?.[0];
  const month = monthNames.find(m => new RegExp("(^|\\\\b)"+m+"(\\\\b|$)","i").test(label));
  if (!year || !month) continue;
  const url = new URL(href,"https://www.onagri.nat.tn/Marche-de-gros-bir-el-kasaa/fr/62").href;
  if (!links.some(x=>x.url===url)) links.push({title:label,url});
  if (links.length===5) break;
}
if (!links.length) throw new Error("No dated monthly Mercuriale links found. Do not send empty prices.");
return links.map(x=>({json:x}));

const items = $input.all();
const months = {janvier:1,fevrier:2,"février":2,mars:3,avril:4,mai:5,juin:6,juillet:7,aout:8,"août":8,septembre:9,octobre:10,novembre:11,decembre:12,"décembre":12};
const decode = s => String(s).replace(/&amp;/g,"&").replace(/&#39;|&apos;/g,"'").replace(/&quot;/g,'"').replace(/&nbsp;/g," ").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&#(\\d+);/g,(_,n)=>String.fromCodePoint(Number(n))).replace(/&#x([0-9a-f]+);/gi,(_,n)=>String.fromCodePoint(parseInt(n,16)));
const clean = s => decode(s.replace(/<[^>]+>/g," ")).replace(/\\s+/g," ").trim();
const number = v => {v=decode(v).replace(/[٠-٩]/g,c=>"٠١٢٣٤٥٦٧٨٩".indexOf(c)).replace(/[%\\s\\u00a0]/g,"").replace(/,/g,".");v=v.replace(/[^0-9.\\-]/g,"");if(!v||v==="."||v==="-"||v==="-.")return null;const n=Number(v);return Number.isFinite(n)?n:null;};
const slug = s => {const ascii=s.normalize("NFKD").replace(/[\\u0300-\\u036f]/g,"").replace(/[^a-zA-Z0-9]+/g,"-").replace(/^-|-$/g,"").toLowerCase();if(ascii)return ascii;let h=0;for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))>>>0;return "ar-"+h.toString(16);};
const prices=[];
for (const item of items) {
 const title=String(item.json.title??""); const url=String(item.json.url??"");
 const year=Number(title.match(/20\\d{2}/)?.[0]);
 const monthName=Object.keys(months).find(m=>new RegExp("(^|\\\\b)"+m+"(\\\\b|$)","i").test(title));
 const month=months[monthName];
 if(!year||!month) throw new Error("Cannot determine report month/year: "+title);
 const start=new Date(Date.UTC(year,month-1,1)).toISOString().slice(0,10);
 const end=new Date(Date.UTC(year,month,0)).toISOString().slice(0,10);
 const html=String(item.json.reportHtml??item.json.body??item.json.data??"");
 if(html.length<300) throw new Error("Monthly report HTML missing/too short: "+title);
 for(const tr of html.matchAll(/<tr\\b[^>]*>([\\s\\S]*?)<\\/tr>/gi)){
   const cells=[...tr[1].matchAll(/<(?:td|th)\\b[^>]*>([\\s\\S]*?)<\\/(?:td|th)>/gi)].map(m=>clean(m[1]));
   if(cells.length<8) continue;
   const c=cells.slice(-8); const crop=c[7]; const days=number(c[0]); const priceChange=number(c[1]); const previous=number(c[2]); const current=number(c[3]); const supplyChange=number(c[4]); const supply=number(c[6]);
   if(!crop||current===null||current<=0) continue;
   prices.push({external_id:year+"-"+String(month).padStart(2,"0")+":"+slug(crop),crop_name:crop,market_location:"Bir El Kassaa",price_kind:"wholesale",price_per_kg:Number((current/1000).toFixed(3)),previous_year_price:previous===null?null:Number((previous/1000).toFixed(3)),source_url:url,price_date:start,period_start:start,period_end:end,aggregation_period:"monthly",unit:"kg",currency:"TND",supply_quantity_tons:supply,supply_change_percent:supplyChange,price_change_percent:priceChange,observation_days:days===null?null:Math.trunc(days),raw_source:{document_title:title,document_url:url,previous_year_price_millimes_per_kg:previous,current_year_price_millimes_per_kg:current,previous_year_supply_tons:number(c[5]),current_year_supply_tons:supply,source_cells:c}});
 }
}
const unique=[...new Map(prices.map(p=>[p.external_id,p])).values()];
if(!unique.length) throw new Error("No monthly commodity price rows parsed; refusing to ingest an empty payload.");
return [{json:{source_key:"tn-onagri-bir-el-kassaa",source_name:"ONAGRI - Mercuriale du marché de gros de Bir El Kassaa",source_url:"https://www.onagri.nat.tn/Marche-de-gros-bir-el-kasaa/fr/62",source_type:"permitted_scrape",verification_status:"official-source",prices:unique,collector_meta:{reports_checked:items.length,rows_parsed:unique.length,aggregation_period:"monthly",unit_conversion:"millimes/kg to TND/kg"}}}];
